    /// <summary>Returns the icon with the given name, or the folder icon when the name is missing or unknown.</summary>
    public static IconSource Resolve(string? name) => name is not null && Catalog.TryGetValue(name, out IconSource? icon) ? icon : AppIcons.Folder;

    /// <summary>The preset hex colours offered for a project icon.</summary>
    public static IReadOnlyList<string> Presets { get; } = ["#EF4444", "#F97316", "#EAB308", "#22C55E", "#06B6D4", "#3B82F6", "#6366F1", "#A855F7"];
}
